1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"io/fs"
9		"os"
10		"path/filepath"
11	
12		"github.com/entireio/cli/cmd/entire/cli/interactive"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15		"github.com/entireio/cli/cmd/entire/cli/session"
16		"github.com/entireio/cli/cmd/entire/cli/settings"
17		"github.com/entireio/cli/cmd/entire/cli/strategy"
18	
19		"charm.land/huh/v2"
20	)
21	
22	// globalTrackingHint is the one-line pointer printed by non-interactive
23	// enable paths when the machine-wide question has never been answered.
24	const globalTrackingHint = "To track every repo on this machine automatically, run 'entire enable --global'."
25	
26	// runEnableGlobalMode turns the user-global tracking tier on. It only writes
27	// the user settings file (preserving existing exclude lists) and never touches
28	// repo-level settings, so it works outside a git repository too.
29	func runEnableGlobalMode(ctx context.Context, w io.Writer) error {
30		us, err := settings.LoadUserSettings(ctx)
31		if err != nil {
32			return unreadableUserSettingsError(err)
33		}
34		if us.Global == nil {
35			us.Global = &settings.GlobalConfig{}
36		}
37		us.Global.Enabled = true
38		if err := settings.SaveUserSettings(ctx, us); err != nil {
39			return fmt.Errorf("saving user settings: %w", err)
40		}
41		fmt.Fprintln(w, "Global tracking enabled.")
42		fmt.Fprintln(w, "Entire now tracks agent sessions in every repo on this machine that has no repo-level setup and matches no exclude pattern.")
43		if kept := len(us.Global.ExcludePaths) + len(us.Global.ExcludeOrigins); kept > 0 {
44			fmt.Fprintf(w, "Keeping %d exclude pattern(s) from your user settings.\n", kept)
45		}
46		return nil
47	}
48	
49	// runDisableGlobalMode turns the user-global tracking tier off. The answer is
50	// durable: the file keeps global.enabled=false (rather than being removed), so
51	// the setup wizard never re-asks. Repo-level settings are not touched.
52	func runDisableGlobalMode(ctx context.Context, w io.Writer) error {
53		us, err := settings.LoadUserSettings(ctx)
54		if err != nil {
55			return unreadableUserSettingsError(err)
56		}
57		if us.Global == nil {
58			us.Global = &settings.GlobalConfig{}
59		}
60		us.Global.Enabled = false
61		if err := settings.SaveUserSettings(ctx, us); err != nil {
62			return fmt.Errorf("saving user settings: %w", err)
63		}
64		fmt.Fprintln(w, "Global tracking disabled.")
65		return nil
66	}
67	
68	// unreadableUserSettingsError turns a LoadUserSettings failure into an
69	// actionable message: the strict decoder also rejects files written by a
70	// newer CLI, so name the file and both ways out.
71	func unreadableUserSettingsError(err error) error {
72		return fmt.Errorf("cannot update user settings at %s: %w; fix or remove the file (an unknown key means a newer entire wrote it — upgrade instead)",
73			settings.UserSettingsPath(), err)
74	}
75	
76	// maybeAskGlobalTracking asks the one-time machine-wide tracking question
77	// during interactive setup. It never asks when the global tier is already
78	// configured (either answer), and never prompts in non-interactive contexts
79	// (--yes, no TTY) — those get the one-line hint instead. An answered prompt
80	// is persisted either way, so the question is never asked twice; a cancelled
81	// prompt saves nothing, so a later enable can ask again.
82	func maybeAskGlobalTracking(ctx context.Context, w io.Writer, opts EnableOptions) {
83		us, err := settings.LoadUserSettings(ctx)
84		if err != nil {
85			// A malformed user settings file must never be overwritten from a
86			// side prompt — but full silence would hide the problem, so name the
87			// file and the ways out (one line, enable itself still succeeds).
88			fmt.Fprintf(w, "Warning: %v\n", unreadableUserSettingsError(err))
89			return
90		}
91		if us.Global != nil {
92			// A configured tier (either answer) must never re-ask.
93			return
94		}
95		if opts.Yes || !interactive.CanPromptInteractively() {
96			fmt.Fprintln(w, globalTrackingHint)
97			return
98		}
99		enable, err := askGlobalTrackingConfirm(ctx)
100		if err != nil {
101			// Ctrl-C stays silent (nothing saved, a later enable asks again);
102			// any other prompt failure must at least be diagnosable.
103			if !errors.Is(err, huh.ErrUserAborted) && !errors.Is(err, context.Canceled) {
104				logging.Debug(ctx, "global tracking prompt failed", "error", err)
105			}
106			return
107		}
108		us.Global = &settings.GlobalConfig{Enabled: enable}
109		if err := settings.SaveUserSettings(ctx, us); err != nil {
110			fmt.Fprintf(w, "Warning: could not save the global tracking answer: %v\n", err)
111			return
112		}
113		if enable {
114			fmt.Fprintln(w, "  ✓ Global tracking enabled")
115		}
116	}
117	
118	// askGlobalTrackingConfirm runs the machine-wide tracking confirm prompt and
119	// returns the answer. A package var (same seam pattern as migrateRenameFile)
120	// so tests can pin the persistence contract of each outcome — durable yes,
121	// durable no, cancelled — without a TTY.
122	var askGlobalTrackingConfirm = func(ctx context.Context) (bool, error) {
123		enable := false
124		form := NewAccessibleForm(
125			huh.NewGroup(
126				huh.NewConfirm().
127					Title("Also track every repo on this machine automatically?").
128					Description("Applies to repos without their own Entire setup.").
129					Affirmative("Yes").
130					Negative("No").
131					Value(&enable),
132			),
133		)
134		if err := form.RunWithContext(ctx); err != nil {
135			return false, err //nolint:wrapcheck // caller classifies huh.ErrUserAborted/context.Canceled
136		}
137		return enable, nil
138	}
139	
140	// printGlobalTrackingHintIfUnconfigured prints the enable --global pointer on
141	// enable paths that must never prompt (--agent), when the machine-wide
142	// question has never been answered.
143	func printGlobalTrackingHintIfUnconfigured(ctx context.Context, w io.Writer) {
144		us, err := settings.LoadUserSettings(ctx)
145		if err != nil || us.Global != nil {
146			return
147		}
148		fmt.Fprintln(w, globalTrackingHint)
149	}
150	
151	// ensureRepoLevelTakeover runs the bookkeeping owed whenever repo-level
152	// settings take over a clone the user-global tier was (or may have been)
153	// tracking. It is invoked from EVERY path that creates the first repo-level
154	// settings file — the interactive and --agent enable flows, the raw
155	// enable/disable flag flip (a bare `entire disable` also creates the routing
156	// discriminator) — plus `entire enable` on an already-configured repo, which
157	// is the user-initiated recovery point for clones a pre-fix binary stranded.
158	//
159	// It self-guards on the migration's own trigger logic (the clone's
160	// global_setup_completed marker, or a non-empty routed runtime dir), so it is
161	// a cheap no-op for repos the global tier never touched. When the guard
162	// holds it, in order:
163	//  1. ensures .entire/.gitignore exists, so the migrated runtime files are
164	//     never visible in git status (order is load-bearing);
165	//  2. migrates this worktree's routed runtime data into .entire/;
166	//  3. clears the global_setup_completed marker — repo-level machinery owns
167	//     hooks now, and a stale marker would short-circuit the lazy global
168	//     setup if the repo ever returns to global-only tracking.
169	//
170	// It always clears the invisible-routing cache: the settings file being
171	// created (or having been created) is the routing discriminator, and the
172	// writer process must observe its own write.
173	func ensureRepoLevelTakeover(ctx context.Context, w io.Writer) {
174		defer paths.ClearInvisibleRuntimeCache()
175		if !globalTakeoverRelevant(ctx) {
176			return
177		}
178		if err := strategy.EnsureEntireGitignore(ctx); err != nil {
179			logging.Warn(ctx, "repo takeover: could not ensure .entire/.gitignore before migrating runtime data", "error", err)
180		}
181		maybeMigrateGlobalRuntimeData(ctx, w)
182		clearGlobalSetupMarker(ctx)
183	}
184	
185	// globalTakeoverRelevant reports whether the global tier is or was relevant
186	// for this clone: the once-per-clone lazy-setup marker is set, or the current
187	// worktree's routed runtime dir is non-empty. This is the same trigger logic
188	// maybeMigrateGlobalRuntimeData applies.
189	func globalTakeoverRelevant(ctx context.Context) bool {
190		if prefs, err := settings.LoadClonePreferences(ctx); err == nil && prefs.GlobalSetupCompleted {
191			return true
192		}
193		source, _, err := invisibleRuntimeLocations(ctx)
194		if err != nil {
195			return false
196		}
197		entries, err := os.ReadDir(source)
198		return err == nil && len(entries) > 0
199	}
200	
201	// clearGlobalSetupMarker clears the clone's global_setup_completed marker so
202	// the lazy invisible setup re-runs the next time the global tier owns this
203	// clone. Read-before-write keeps the common case (marker absent) to one
204	// preferences read, without taking the preferences lock. Best-effort: a
205	// failure is logged, and the stale marker's only cost is that a later
206	// globally-tracked session skips hook reinstallation until doctor clears it.
207	func clearGlobalSetupMarker(ctx context.Context) {
208		if prefs, err := settings.LoadClonePreferences(ctx); err != nil || !prefs.GlobalSetupCompleted {
209			return
210		}
211		if err := settings.ModifyClonePreferences(ctx, func(p *settings.ClonePreferences) error {
212			p.GlobalSetupCompleted = false
213			return nil
214		}); err != nil {
215			logging.Warn(ctx, "could not clear the global_setup_completed marker", "error", err)
216		}
217	}
218	
219	// invisibleRuntimeLocations resolves the current worktree's routed runtime
220	// dir (<git-common-dir>/entire/worktree/<worktree-key>) and the worktree
221	// root. session.GetGitCommonDir returns an absolute path (relative rev-parse
222	// output is absolutized against the cwd it was resolved in), satisfying
223	// InvisibleRuntimeDir's absolute-commonDir precondition.
224	func invisibleRuntimeLocations(ctx context.Context) (source, root string, err error) {
225		root, err = paths.WorktreeRoot(ctx)
226		if err != nil {
227			return "", "", fmt.Errorf("resolve worktree root: %w", err)
228		}
229		commonDir, err := session.GetGitCommonDir(ctx)
230		if err != nil {
231			return "", "", fmt.Errorf("resolve git common dir: %w", err)
232		}
233		source, err = paths.InvisibleRuntimeDir(commonDir, root)
234		if err != nil {
235			return "", "", fmt.Errorf("classify worktree: %w", err)
236		}
237		return source, root, nil
238	}
239	
240	// maybeMigrateGlobalRuntimeData moves THIS worktree's invisible-routed
241	// runtime data (<git-common-dir>/entire/worktree/<worktree-key>/
242	// {metadata,logs,tmp} — the subtrees paths.InvisibleRuntimeSubdirs
243	// enumerates) into the worktree's .entire directory. Repo-level enable flows
244	// call it (via ensureRepoLevelTakeover) BEFORE writing .entire/settings.json:
245	// that write flips path routing to the worktree, which would otherwise strand
246	// the routed files in .git. Only the current worktree's namespace is touched
247	// — sibling worktrees of the same clone keep their own namespaces (and their
248	// in-flight sessions) untouched. It triggers when the clone preferences carry
249	// the global_setup_completed marker or when the routed directory is
250	// non-empty. Best-effort by contract — enable never aborts on migration
251	// failure; files that could not be moved stay in place for a later retry and
252	// the outcome is summarized in one line. When the routed location itself
253	// cannot be resolved while the marker says there may be data, the early
254	// return logs one Warn — the data stays under .git and the marker persists,
255	// so a later enable retries.
256	func maybeMigrateGlobalRuntimeData(ctx context.Context, w io.Writer) {
257		markerSet := false
258		if prefs, prefsErr := settings.LoadClonePreferences(ctx); prefsErr == nil && prefs.GlobalSetupCompleted {
259			markerSet = true
260		}
261		source, root, err := invisibleRuntimeLocations(ctx)
262		if err != nil {
263			if markerSet {
264				logging.Warn(ctx, "global runtime data migration skipped: routed location unresolved; any routed data stays under .git until a later enable retries", "error", err)
265			}
266			return
267		}
268	
269		if !markerSet {
270			entries, readErr := os.ReadDir(source)
271			if readErr != nil || len(entries) == 0 {
272				return
273			}
274		}
275	
276		var moved, skipped, failed int
277		for _, sub := range paths.InvisibleRuntimeSubdirs() {
278			m, s, f := moveDirContents(ctx, filepath.Join(source, sub), filepath.Join(root, paths.EntireDir, sub))
279			moved += m
280			skipped += s
281			failed += f
282		}
283		removeEmptyDirTree(source)
284		// The parent (<git-common-dir>/entire/worktree) is shared with sibling
285		// worktrees' namespaces; os.Remove only succeeds once the last namespace
286		// is gone, which is exactly the desired cleanup.
287		_ = os.Remove(filepath.Dir(source))
288	
289		if moved+skipped+failed == 0 {
290			return
291		}
292		// ✓ elsewhere in the enable output means unqualified success, so drop it
293		// when anything failed, and name the source so leftovers are findable.
294		prefix := "  ✓ "
295		if failed > 0 {
296			prefix = "  "
297		}
298		line := fmt.Sprintf("%sMoved %d globally-tracked file(s) into .entire/", prefix, moved)
299		if skipped > 0 {
300			line += fmt.Sprintf(", %d already present", skipped)
301		}
302		if failed > 0 {
303			line += fmt.Sprintf(", %d could not be moved (left in %s)", failed, source)
304		}
305		fmt.Fprintln(w, line)
306	}
307	
308	// migrateRenameFile is the rename used by moveDirContents; a seam so tests
309	// can force the cross-device (EXDEV) fallback deterministically.
310	var migrateRenameFile = os.Rename
311	
312	// moveDirContents moves every file under src into the same relative location
313	// under dst, creating directories as needed. Files already present in dst are
314	// skipped (left in src). Returns moved/skipped/failed counts; a missing src is
315	// (0, 0, 0), while any other ReadDir failure counts as one failure — an
316	// unreadable source is not "nothing to move", and the summary must not claim
317	// unqualified success over it. The summary line keeps the counts; every
318	// individual failure is logged here with its path and reason, so "1 could not
319	// be moved" is diagnosable from the log.
320	func moveDirContents(ctx context.Context, src, dst string) (moved, skipped, failed int) {
321		entries, err := os.ReadDir(src)
322		if err != nil {
323			if errors.Is(err, fs.ErrNotExist) {
324				return 0, 0, 0
325			}
326			logging.Warn(ctx, "global runtime data migration: source directory unreadable", "path", src, "error", err)
327			return 0, 0, 1
328		}
329		for _, entry := range entries {
330			srcPath := filepath.Join(src, entry.Name())
331			dstPath := filepath.Join(dst, entry.Name())
332			if entry.IsDir() {
333				m, s, f := moveDirContents(ctx, srcPath, dstPath)
334				moved, skipped, failed = moved+m, skipped+s, failed+f
335				continue
336			}
337			if _, statErr := os.Lstat(dstPath); statErr == nil {
338				skipped++
339				continue
340			}
341			//nolint:gosec // G301: runtime-data dirs match the .entire directory permissions
342			if mkErr := os.MkdirAll(dst, 0o755); mkErr != nil {
343				logging.Warn(ctx, "global runtime data migration: cannot create destination directory", "path", dst, "error", mkErr)
344				failed++
345				continue
346			}
347			if renameErr := migrateRenameFile(srcPath, dstPath); renameErr != nil {
348				// Rename fails with EXDEV when the git common dir and the
349				// worktree live on different filesystems (--separate-git-dir,
350				// linked worktree on another volume); fall back to copy+remove.
351				copied, copyErr := copyFileThenRemove(srcPath, dstPath)
352				switch {
353				case copyErr == nil:
354					// Fully moved via the fallback.
355				case copied:
356					// The copy landed in .entire; only removing the source
357					// failed. The data IS where the user needs it, so count it
358					// moved — claiming it "could not be moved" would be false —
359					// and record the residue left under .git.
360					logging.Warn(ctx, "global runtime data migration: file copied but source residue remains", "path", srcPath, "error", copyErr)
361				default:
362					logging.Warn(ctx, "global runtime data migration: file could not be moved", "path", srcPath, "rename_error", renameErr, "copy_error", copyErr)
363					failed++
364					continue
365				}
366			}
367			moved++
368		}
369		return moved, skipped, failed
370	}
371	
372	// copyFileThenRemove copies src to dst (temp file in dst's directory, then
373	// rename, so a partial copy is never left at dst) and removes src on success.
374	// Only regular files are copied; anything else stays behind as failed.
375	// copied reports whether dst landed: (true, non-nil error) means the copy
376	// succeeded and only the source removal failed, leaving a residue at src.
377	func copyFileThenRemove(src, dst string) (copied bool, err error) {
378		info, err := os.Lstat(src)
379		if err != nil {
380			return false, fmt.Errorf("stat source: %w", err)
381		}
382		if !info.Mode().IsRegular() {
383			return false, fmt.Errorf("not a regular file: %s", src)
384		}
385		in, err := os.Open(src) //nolint:gosec // path is derived from the git common dir, not user input
386		if err != nil {
387			return false, fmt.Errorf("open source: %w", err)
388		}
389		defer in.Close()
390		tmp, err := os.CreateTemp(filepath.Dir(dst), filepath.Base(dst)+".tmp-*")
391		if err != nil {
392			return false, fmt.Errorf("create temp: %w", err)
393		}
394		tmpName := tmp.Name()
395		removeTmp := true
396		defer func() {
397			if removeTmp {
398				_ = os.Remove(tmpName)
399			}
400		}()
401		if _, err := io.Copy(tmp, in); err != nil {
402			_ = tmp.Close()
403			return false, fmt.Errorf("copy contents: %w", err)
404		}
405		if err := tmp.Chmod(info.Mode().Perm()); err != nil {
406			_ = tmp.Close()
407			return false, fmt.Errorf("chmod temp: %w", err)
408		}
409		if err := tmp.Close(); err != nil {
410			return false, fmt.Errorf("close temp: %w", err)
411		}
412		if err := os.Rename(tmpName, dst); err != nil {
413			return false, fmt.Errorf("rename into place: %w", err)
414		}
415		removeTmp = false
416		if err := os.Remove(src); err != nil {
417			return true, fmt.Errorf("remove source: %w", err)
418		}
419		return true, nil
420	}
421	
422	// removeEmptyDirTree removes the now-empty directories left behind by
423	// moveDirContents, deepest first, including root itself. Non-empty
424	// directories (skipped or failed files) are left in place.
425	func removeEmptyDirTree(root string) {
426		entries, err := os.ReadDir(root)
427		if err != nil {
428			return
429		}
430		for _, entry := range entries {
431			if entry.IsDir() {
432				removeEmptyDirTree(filepath.Join(root, entry.Name()))
433			}
434		}
435		// os.Remove fails on non-empty directories, which is exactly the
436		// keep-what-couldn't-move behavior wanted here.
437		if err := os.Remove(root); err != nil {
438			return
439		}
440	}
441

