diff --git a/cmd/entire/cli/paths/entire_join_guard_test.go b/cmd/entire/cli/paths/entire_join_guard_test.go
index 2772a19d..4c350603 100644
--- a/cmd/entire/cli/paths/entire_join_guard_test.go
+++ b/cmd/entire/cli/paths/entire_join_guard_test.go
@@ -38,6 +38,15 @@ func TestNoDirectEntireJoins(t *testing.T) {
 		// Doctor bundle collects the repo-level settings files for support
 		// bundles; a globally tracked repo has none by definition.
 		"cmd/entire/cli/doctor_bundle.go": "collects repo-level settings files",
+		// The takeover migration's DESTINATION is deliberately the literal
+		// worktree .entire dir, in both of its states: on a fresh enable it
+		// runs before .entire/settings.json exists, when AbsPath still routes
+		// to the git common dir — resolving through AbsPath would move files
+		// onto themselves; on a takeover recovery (enable/disable in a repo
+		// whose settings file already exists) routing already points at the
+		// worktree, and the destination must be that same literal dir
+		// regardless. The join is routing-independent by design.
+		"cmd/entire/cli/setup_global.go": "migration destination, routing-independent by design",
 		// Legacy no-repo fallbacks, guarded by paths.IsUnroutableRuntimePath
 		// so a tier-owned repo can never reach them.
 		"cmd/entire/cli/agent/pi/lifecycle.go":       "sentinel-guarded no-repo fallback",
diff --git a/cmd/entire/cli/settings/settings.go b/cmd/entire/cli/settings/settings.go
index 8aaa739e..11ca11ed 100644
--- a/cmd/entire/cli/settings/settings.go
+++ b/cmd/entire/cli/settings/settings.go
@@ -664,6 +664,11 @@ func saveRaw(path, label string, raw map[string]json.RawMessage) error {
 	if err := jsonutil.WriteFileAtomic(path, data, 0o644); err != nil {
 		return fmt.Errorf("writing %s settings: %w", label, err)
 	}
+	// Same invalidation contract as saveToFile below: a repo settings file's
+	// existence is the invisible-routing discriminator, and the raw path can
+	// CREATE that file (e.g. a bare `entire disable` in a fresh repo), so the
+	// writer process must observe its own write.
+	paths.ClearInvisibleRuntimeCache()
 	return nil
 }

@@ -1604,5 +1609,10 @@ func saveToFile(ctx context.Context, settings *EntireSettings, filePath string)
 	if err := jsonutil.WriteFileAtomic(filePathAbs, data, 0o644); err != nil {
 		return fmt.Errorf("writing settings file: %w", err)
 	}
+	// A repo settings file's existence is the invisible-routing discriminator:
+	// creating one during enable must flip runtime-data resolution back to the
+	// worktree for the rest of this process (e.g. session import right after
+	// enabling a formerly globally-tracked clone).
+	paths.ClearInvisibleRuntimeCache()
 	return nil
 }

